<?php
use App\Models\Tenant;use App\Models\TenantMembership;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;
uses(RefreshDatabase::class);
test('guest is redirected from platform administration',function(){$this->get('/admin')->assertRedirect();});
test('ordinary active tenant member cannot access platform administration',function(){$u=User::factory()->create();$t=Tenant::create(['type'=>'BROKER','legal_name'=>'Test Broker','slug'=>'test-broker','status'=>'ACTIVE','country_code'=>'CM','currency'=>'XAF','primary_locale'=>'en','settings'=>[]]);TenantMembership::create(['tenant_id'=>$t->id,'user_id'=>$u->id,'role_code'=>'CUSTOMER','status'=>'ACTIVE']);expect($u->canAccessPanel(app(\Filament\PanelRegistry::class)->get('admin')))->toBeFalse();});
test('broker staff and commercial agent can access platform administration',function(){$u1=User::factory()->create();$u2=User::factory()->create();$t=Tenant::create(['type'=>'BROKER','legal_name'=>'Test Broker 2','slug'=>'test-broker-2','status'=>'ACTIVE','country_code'=>'CM','currency'=>'XAF','primary_locale'=>'en','settings'=>[]]);TenantMembership::create(['tenant_id'=>$t->id,'user_id'=>$u1->id,'role_code'=>'BROKER_STAFF','status'=>'ACTIVE']);TenantMembership::create(['tenant_id'=>$t->id,'user_id'=>$u2->id,'role_code'=>'AGENT','status'=>'ACTIVE']);$panel=app(\Filament\PanelRegistry::class)->get('admin');expect($u1->canAccessPanel($panel))->toBeTrue();expect($u2->canAccessPanel($panel))->toBeTrue();});
test('system administrator can access platform administration',function(){$u=User::factory()->create();$t=Tenant::create(['type'=>'PLATFORM','legal_name'=>'OpesInsure','slug'=>'opesinsure','status'=>'ACTIVE','country_code'=>'CM','currency'=>'XAF','primary_locale'=>'en','settings'=>[]]);TenantMembership::create(['tenant_id'=>$t->id,'user_id'=>$u->id,'role_code'=>'SYSTEM_ADMIN','status'=>'ACTIVE']);expect($u->canAccessPanel(app(\Filament\PanelRegistry::class)->get('admin')))->toBeTrue();});
